import Foundation
import XCTest

@testable import SinchPushSDK

// MARK: - Fixture

/// Golden vectors generated by the relay's own codec, pinned at relay contract
/// commit `d0e0d80` and bundled in `PushSocket/Fixtures`. `RELAY_GOLDEN` or
/// `RELAY_DIR` override the bundled copy.
enum GoldenFixture {
    static let fileName = "ws_frames.v1beta1.golden"

    static var defaultURL: URL? {
        Bundle.module.url(forResource: fileName, withExtension: "json", subdirectory: "Fixtures")
    }

    static var overrideURL: URL? {
        let environment = ProcessInfo.processInfo.environment
        if let golden = environment["RELAY_GOLDEN"], !golden.isEmpty {
            return URL(fileURLWithPath: golden)
        }
        if let relayDir = environment["RELAY_DIR"], !relayDir.isEmpty {
            return URL(fileURLWithPath: relayDir)
                .appendingPathComponent("testdata/wire/ws_frames.v1beta1.golden.json")
        }
        return nil
    }

    struct MissingBundledFixture: Error, CustomStringConvertible {
        var description: String {
            "bundled golden fixture missing from Bundle.module (PushSocket/Fixtures/\(GoldenFixture.fileName).json)"
        }
    }

    static func load() throws -> Golden {
        if let override = overrideURL {
            guard FileManager.default.fileExists(atPath: override.path) else {
                throw XCTSkip(
                    """
                    relay golden vectors not found at \(override.path) \
                    (RELAY_GOLDEN / RELAY_DIR). Fix the path or unset the override to \
                    use the bundled fixture.
                    """)
            }
            return try JSONDecoder().decode(Golden.self, from: Data(contentsOf: override))
        }
        // The bundled fixture is pinned: absence fails rather than skips.
        guard let url = defaultURL, FileManager.default.fileExists(atPath: url.path) else {
            XCTFail(
                """
                bundled golden fixture missing from Bundle.module \
                (PushSocket/Fixtures/\(fileName).json). Restore it and check the \
                `.copy("PushSocket/Fixtures")` resource rule in Package.swift.
                """)
            throw MissingBundledFixture()
        }
        return try JSONDecoder().decode(Golden.self, from: Data(contentsOf: url))
    }
}

// MARK: - Schema

struct Golden: Decodable {
    struct SizeContract: Decodable {
        let maxFramePayloadBytes: Int
        let maxFrameEnvelopeBytes: Int
        let maxWireFrameBytes: Int
        let canonicalEnvelopeMaxBytes: Int

        enum CodingKeys: String, CodingKey {
            case maxFramePayloadBytes = "max_frame_payload_bytes"
            case maxFrameEnvelopeBytes = "max_frame_envelope_bytes"
            case maxWireFrameBytes = "max_wire_frame_bytes"
            case canonicalEnvelopeMaxBytes = "canonical_envelope_max_bytes"
        }
    }

    struct FrameType: Decodable {
        let direction: Direction
        let tag: Int
        let frameType: String

        enum CodingKeys: String, CodingKey {
            case direction, tag
            case frameType = "frame_type"
        }
    }

    struct Frame: Decodable {
        let name: String
        let direction: Direction
        let tag: Int
        let frameType: String
        let payloadLen: Int
        let frameHex: String

        enum CodingKeys: String, CodingKey {
            case name, direction, tag, payloadLen = "payload_len", frameHex = "frame_hex"
            case frameType = "frame_type"
        }
    }

    struct NegativeCase: Decodable {
        let name: String
        let direction: Direction
        let expect: String
        let frameHex: String

        enum CodingKeys: String, CodingKey {
            case name, direction, expect
            case frameHex = "frame_hex"
        }
    }

    enum Direction: String, Decodable {
        case clientToServer = "client_to_server"
        case serverToClient = "server_to_client"
    }

    let version: Int
    let sizeContract: SizeContract
    let frameTypes: [FrameType]
    let frames: [Frame]
    let negativeCases: [NegativeCase]

    enum CodingKeys: String, CodingKey {
        case version, frames
        case sizeContract = "size_contract"
        case frameTypes = "frame_types"
        case negativeCases = "negative_cases"
    }
}

// MARK: - Wire

enum GoldenWire {

    static func decode(_ direction: Golden.Direction, _ frame: Data) throws {
        switch direction {
        case .clientToServer: _ = try FrameCodec.decodeClientFrame(frame)
        case .serverToClient: _ = try FrameCodec.decodeServerFrame(frame)
        }
    }

    static func encode(_ direction: Golden.Direction, _ frame: Data) throws -> Data {
        switch direction {
        case .clientToServer: return try FrameCodec.encodeClientFrame(FrameCodec.decodeClientFrame(frame))
        case .serverToClient: return try FrameCodec.encodeServerFrame(FrameCodec.decodeServerFrame(frame))
        }
    }

    /// Map entries are written sorted by the relay but in hash order by SwiftProtobuf,
    /// so map-bearing vectors cannot be compared byte for byte.
    static func carriesMapEntries(
        _ payload: Sinch_Push_Delivery_V1beta1_Ws_ServerFrame.OneOf_Payload
    ) -> Bool {
        var notification: Sinch_Push_V1beta1_Resources_PushNotification?
        switch payload {
        case .helloAck(let ack): notification = ack.messages.first?.pushNotification
        case .message(let message): notification = message.message.pushNotification
        default: break
        }
        return !(notification?.metadata.isEmpty ?? true)
    }

    // MARK: - Names

    static func frameTypeComponent(_ frameType: String) -> String {
        frameType.split(separator: ".").last.map(String.init) ?? frameType
    }

    /// `delivery_report` -> `deliveryReport`.
    static func camelCase(_ snake: String) -> String {
        var out = ""
        var upperNext = false
        for character in snake {
            if character == "_" {
                upperNext = true
            } else if upperNext {
                out.append(Character(character.uppercased()))
                upperNext = false
            } else {
                out.append(character)
            }
        }
        return out
    }

    static func clientCaseName(
        _ payload: Sinch_Push_Delivery_V1beta1_Ws_ClientFrame.OneOf_Payload?
    ) -> String {
        switch payload {
        case .hello?: return "hello"
        case .poll?: return "poll"
        case .deliveryReport?: return "deliveryReport"
        case .pong?: return "pong"
        case .none: return "none"
        }
    }

    static func serverCaseName(
        _ payload: Sinch_Push_Delivery_V1beta1_Ws_ServerFrame.OneOf_Payload?
    ) -> String {
        switch payload {
        case .authChallenge?: return "authChallenge"
        case .helloAck?: return "helloAck"
        case .message?: return "message"
        case .ack?: return "ack"
        case .ping?: return "ping"
        case .pong?: return "pong"
        case .close?: return "close"
        case .none: return "none"
        }
    }

    static func clientFrameFor(frameType: String) -> Sinch_Push_Delivery_V1beta1_Ws_ClientFrame {
        switch frameTypeComponent(frameType) {
        case "hello": return helloClientFrame()
        case "poll": return pollClientFrame()
        case "delivery_report": return deliveryReportClientFrame()
        case "pong": return Wire.pongClientFrameOfSize(0)
        default: preconditionFailure("the relay names a client payload this SDK does not: \(frameType)")
        }
    }

    static func serverFrameFor(frameType: String) -> Sinch_Push_Delivery_V1beta1_Ws_ServerFrame {
        switch frameTypeComponent(frameType) {
        case "auth_challenge": return authChallengeServerFrame()
        case "hello_ack": return helloAckServerFrame()
        case "message": return messageServerFrame()
        case "ack": return ackServerFrame()
        case "ping": return pingServerFrame()
        case "pong": return pongServerFrame()
        case "close": return closeServerFrame()
        default: preconditionFailure("the relay names a server payload this SDK does not: \(frameType)")
        }
    }
}

// MARK: - Classification

enum GoldenClassification {

    /// The relay's "unexpected EOF" maps to `truncatedPayload` or `lengthVarint`, so each
    /// `expect` string accepts a set of ``FrameCodecError`` cases.
    static func acceptable(_ error: FrameCodecError, for expect: String) -> Bool {
        switch expect {
        case "unexpected EOF":
            if case .truncatedPayload = error { return true }
            if case .lengthVarint = error { return true }
            return false
        case "frame_too_large":
            if case .payloadTooLarge = error { return true }
            if case .frameTooLarge = error { return true }
            return false
        case "varint overflows uint64":
            if case .lengthVarint = error { return true }
            return false
        case "unknown_type_tag", "wrong_direction_tag":
            // A server-only tag read on the client side is an unknown tag here.
            if case .unknownTag = error { return true }
            return false
        default:
            XCTFail("the fixture names an expectation this suite does not classify: \(expect)")
            return false
        }
    }
}

// MARK: - Hello fixtures

/// The device-info fields of a Hello, compared field by field.
struct GoldenDeviceInfo: Equatable {
    let installationID: String
    let osVersion: String
    let bundleID: String
    let backgroundService: Sinch_Push_V1beta1_Resources_BackgroundServiceState

    init(
        installationID: String,
        osVersion: String,
        bundleID: String,
        backgroundService: Sinch_Push_V1beta1_Resources_BackgroundServiceState
    ) {
        self.installationID = installationID
        self.osVersion = osVersion
        self.bundleID = bundleID
        self.backgroundService = backgroundService
    }

    init(_ hello: Sinch_Push_Delivery_V1beta1_Ws_Hello) {
        self.init(
            installationID: hello.installationID,
            osVersion: hello.osVersion,
            bundleID: hello.bundleID,
            backgroundService: hello.backgroundService)
    }
}

/// Every field of the `client_hello_relay_disabled` vector.
struct GoldenRelayDisabledHello: Equatable {
    let authToken: String
    let projectID: String
    let appID: String
    let userID: String
    let platform: Sinch_Push_Delivery_V1beta1_Ws_Platform
    let background: Bool
    let lastSeenMessageID: String
    let sdkVersion: String
    let installationID: String
    let osVersion: String
    let bundleID: String
    let backgroundService: Sinch_Push_V1beta1_Resources_BackgroundServiceState

    init(_ hello: Sinch_Push_Delivery_V1beta1_Ws_Hello) {
        self.authToken = hello.authToken
        self.projectID = hello.projectID
        self.appID = hello.appID
        self.userID = hello.userID
        self.platform = hello.platform
        self.background = hello.background
        self.lastSeenMessageID = hello.lastSeenMessageID
        self.sdkVersion = hello.sdkVersion
        self.installationID = hello.installationID
        self.osVersion = hello.osVersion
        self.bundleID = hello.bundleID
        self.backgroundService = hello.backgroundService
    }
}

/// A pinned vector that is missing or changed is a failure, not an `XCTSkip`.
enum GoldenVectorError: Error, CustomStringConvertible {
    case missing(String)
    case notAHello(String)
    case rewriteIsNotAHello(String)

    var description: String {
        switch self {
        case .missing(let name):
            return "the fixture no longer carries \(name)"
        case .notAHello(let name):
            return "\(name) is not a ClientFrame.hello any more"
        case .rewriteIsNotAHello(let name):
            return "\(name): the rewritten frame no longer decodes as a Hello"
        }
    }
}

enum GoldenHelloVectors {

    /// Device-info vectors for Hello fields 9-12.
    static let deviceInfo: [(name: String, expected: GoldenDeviceInfo)] = [
        (
            "client_hello_device_info",
            GoldenDeviceInfo(
                installationID: "6f1c2a9e-3b7d-4e8a-9c21-5d4b7a0e1f23",
                osVersion: "18.1",
                bundleID: "com.sinch.example",
                backgroundService: .unsupported)
        ),
        (
            "client_hello_android_bg_running",
            GoldenDeviceInfo(
                installationID: "0b8f3d52-7c1e-4a96-b5d0-2e9f6a4c8d17",
                osVersion: "14",
                bundleID: "com.sinch.example",
                backgroundService: .enabledRunning)
        ),
        // 99 is undefined in this proto version and must survive as UNRECOGNIZED.
        (
            "client_hello_unknown_background_service",
            GoldenDeviceInfo(
                installationID: "0b8f3d52-7c1e-4a96-b5d0-2e9f6a4c8d17",
                osVersion: "14",
                bundleID: "com.sinch.example",
                backgroundService: .UNRECOGNIZED(99))
        ),
        // Must decode as the named case, not UNRECOGNIZED(5).
        (
            "client_hello_relay_disabled",
            GoldenDeviceInfo(
                installationID: "3c9e1f7a-52b4-4d08-9a6e-1b7c2d5e8f40",
                osVersion: "14",
                bundleID: "com.sinch.example",
                backgroundService: .relayDisabled)
        ),
    ]

    /// Written out rather than read back: the relay pins the bytes, this pins the meaning.
    static let relayDisabled = GoldenRelayDisabledHello(
        Sinch_Push_Delivery_V1beta1_Ws_Hello.with {
            $0.authToken = "header.payload.signature"
            $0.projectID = "proj-1"
            $0.appID = "app-1"
            $0.userID = "user-1"
            $0.platform = .android
            $0.background = false
            $0.lastSeenMessageID = "m-last"
            $0.sdkVersion = "1.2.3"
            $0.installationID = "3c9e1f7a-52b4-4d08-9a6e-1b7c2d5e8f40"
            $0.osVersion = "14"
            $0.bundleID = "com.sinch.example"
            $0.backgroundService = .relayDisabled
        })

    static func vector(
        _ golden: Golden, named name: String
    ) throws -> (vector: Golden.Frame, hello: Sinch_Push_Delivery_V1beta1_Ws_Hello) {
        guard let vector = golden.frames.first(where: { $0.name == name }) else {
            throw GoldenVectorError.missing(name)
        }
        let frame = try FrameCodec.decodeClientFrame(Data(Wire.bytes(hex: vector.frameHex)))
        guard case .some(.hello(let hello)) = frame.payload else {
            throw GoldenVectorError.notAHello(name)
        }
        return (vector, hello)
    }
}
